const CM_JUNTAS = /pago(?:fue)?(?:acreditad|verificad|recibid)|recibimos(?:tu|su)?pago|nosoyun(?:bot|robot|maquina)|soyunapersona|quedoagendad|yaagende|teagende|agende(?:tu|su|la|el)(?:cita|turno|reserva)/g;
